<script lang="ts">
	import { formatName, pluralize } from '$lib/formatting';
	import { requestStatusKey, statusLabel, STATUS_COLORS } from '$lib/request-status';
	import StatCard from '$lib/components/ui/StatCard.svelte';
	import Badge from '$lib/components/ui/Badge.svelte';
	import EmptyState from '$lib/components/ui/EmptyState.svelte';
	import type { PageData } from './$types';
	import { onMount } from 'svelte';
	import Button from '$lib/components/ui/Button.svelte';
	import { fetchAdminRequests, recentActivity, type AdminRequest } from '$lib/admin-requests';
	import { showToast } from '$lib/stores/toasts';

	const { data }: { data: PageData } = $props();
	let submittedRequests = $state<AdminRequest[] | null>(null);
	const activity = $derived(recentActivity(data.recentActivity, submittedRequests ?? data.pendingQueue as unknown as AdminRequest[]));
	const verification = $derived(data.role === 'Admin' ? data.counts.pendingVerification : 0);
	const attention = $derived(verification + data.counts.awaitingCorrections + data.counts.awaitingDelivery);
	onMount(() => { void fetchAdminRequests().then(requests => { submittedRequests = requests; }).catch(error => showToast(error.message, 'error')); });

	const activityIcons: Record<string, string> = {
		pending: 'fa-solid fa-clock', correction_requested: 'fa-solid fa-rotate-left',
		approved: 'fa-solid fa-circle-check', processing: 'fa-solid fa-gears',
		ready_for_pickup: 'fa-solid fa-box', released: 'fa-solid fa-handshake',
		rejected: 'fa-solid fa-circle-xmark', cancelled: 'fa-solid fa-ban'
	};
</script>
<div class="space-y-8">
 <div class="ui-stat-grid"><a href="/staff/students"><StatCard label="Total students" value={data.counts.students} icon="fa-solid fa-users" color="blue" /></a><a href="/staff/requests"><StatCard label="Total requests" value={data.counts.requests} icon="fa-solid fa-file-lines" color="teal" /></a><a href="/staff/requests?status=Pending"><StatCard label="Pending review" value={data.counts.pending} icon="fa-solid fa-clock" color="orange" /></a><a href="/staff/requests?status=Approved"><StatCard label="Approved" value={data.counts.approved} icon="fa-solid fa-circle-check" /></a></div>
 <section class="attention-strip" class:has-attention={attention > 0} aria-label="Needs attention"><div><h2>Needs attention</h2><div class="attention-counts">{#if data.role==='Admin'}<a href="/staff/students?status=pending"><strong>{verification}</strong> IDs awaiting verification</a>{/if}<a href="/staff/requests?status=Correction%20Requested"><strong>{data.counts.awaitingCorrections}</strong> awaiting corrections</a><a href="/staff/requests?status=Approved&amp;delivery=waiting"><strong>{data.counts.awaitingDelivery}</strong> awaiting delivery</a></div>{#if !attention}<p class="text-xs text-gray-500 mt-2">Everything is up to date.</p>{/if}</div>{#if attention > 0}<Button href={verification ? '/staff/students?status=pending' : data.counts.awaitingDelivery ? '/staff/requests?status=Approved&delivery=waiting' : '/staff/requests?status=Correction%20Requested'}>Review</Button>{/if}</section>
 <div class="dashboard-columns"><section class="dashboard-card"><header><div><h2>Needs action</h2><p>{data.pendingQueue.length} {pluralize(data.pendingQueue.length,'request')} awaiting action</p></div><Button variant="ghost" href="/staff/requests" icon="fa-solid fa-arrow-right" iconRight>View all</Button></header>{#if !data.pendingQueue.length}<EmptyState title="No requests need action" description="You're up to date. Check all requests for their progress.">{#snippet action()}<Button variant="secondary" href="/staff/requests">View requests</Button>{/snippet}</EmptyState>{:else}<div class="md:hidden">{#each data.pendingQueue as req}<article class="queue-card"><p class="font-semibold">{formatName(req.first_name,req.middle_name,req.last_name)}</p><p class="text-xs text-gray-500">{req.request_id}</p><p>{req.document_name}</p><Badge value={req.status as string}/><Button href={'/staff/requests/'+req.request_id} icon="fa-solid fa-eye">Review</Button></article>{/each}</div><div class="hidden md:block"><table class="office-queue-table"><thead><tr>{#each ['Request ID','Student','Document','Date','Action'] as col}<th class="text-left">{col}</th>{/each}</tr></thead><tbody>{#each data.pendingQueue as req}<tr><td class="text-xs font-mono">{req.request_id}</td><td><p class="font-medium">{formatName(req.first_name,req.middle_name,req.last_name)}</p><p class="text-xs text-gray-500">{req.student_id ?? '—'}{req.program ? ' · '+req.program:''}</p></td><td>{req.document_name}</td><td>{new Date(req.date_requested as string).toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric',timeZone:'Asia/Manila'})}</td><td><Button size="sm" href={'/staff/requests/'+req.request_id} icon="fa-solid fa-eye">Review</Button></td></tr>{/each}</tbody></table></div>{/if}</section>
 <section class="dashboard-card"><header><h2>Recent activity</h2></header>{#if !activity.length}<EmptyState title="No recent activity" description="New request updates will appear here.">{#snippet action()}<Button variant="secondary" href="/staff/requests">View requests</Button>{/snippet}</EmptyState>{:else}{#each activity as item}<div class="activity-row"><span class="activity-icon"><i class={item.new_status==='Request submitted'?'fa-solid fa-file-circle-plus':activityIcons[requestStatusKey(item.new_status as string)??'']??'fa-solid fa-gear'} aria-hidden="true"></i></span><div><p class="font-medium">{item.document_name}: {item.new_status==='Request submitted'?'Request submitted':statusLabel(item.new_status as string)}</p><p class="text-xs text-gray-500">{formatName(item.first_name,item.middle_name,item.last_name)} · {new Date(item.changed_at as string).toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric',timeZone:'Asia/Manila'})}</p></div></div>{/each}{/if}</section></div>
</div>
<style>.attention-strip {display:flex;align-items:center;justify-content:space-between;gap:var(--space-4);padding:var(--space-6);border:1px solid var(--color-border);border-radius:var(--radius-card);background:var(--color-surface-muted);} .attention-strip.has-attention {background:var(--color-warning-soft);border-color:var(--color-warning-border);} h2 {font-size:var(--type-card-title);font-weight:var(--weight-semibold);} .attention-counts {display:flex;flex-wrap:wrap;gap:var(--space-4);margin-top:var(--space-2);color:var(--color-text-muted);} .attention-counts a:hover {color:var(--color-primary);} .dashboard-columns {display:grid;grid-template-columns:minmax(0,2fr) minmax(0,1fr);gap:var(--space-6);align-items:start;} .dashboard-card {min-width:0;border:1px solid var(--color-border);border-radius:var(--radius-card);background:var(--color-surface);overflow:hidden;} .dashboard-card header {display:flex;align-items:center;justify-content:space-between;gap:var(--space-3);padding:var(--space-6);border-bottom:1px solid var(--color-border);} header p {font-size:var(--type-helper);color:var(--color-text-muted);} .activity-row {display:flex;gap:var(--space-3);padding:var(--space-4) var(--space-6);border-bottom:1px solid var(--color-border);} .activity-icon {width:32px;height:32px;flex-shrink:0;display:grid;place-items:center;border-radius:var(--radius-control);background:var(--color-info-soft);color:var(--color-info);} .queue-card {display:grid;gap:var(--space-3);padding:var(--space-6);border-bottom:1px solid var(--color-border);} @media(max-width:1099px){.dashboard-columns {grid-template-columns:1fr;}} @media(max-width:639px){.attention-strip {align-items:flex-start;flex-direction:column;}}</style>
